  'handoff.promptIntro': 'ఈ లోకల్ Open Design ప్రాజెక్ట్ ఫోల్డర్ నుండి కొనసాగండి:',
  'handoff.promptTarget': 'లక్ష్యం',
  'handoff.promptCli': 'CLI',
  'handoff.promptStepsLead': 'మీరు {cli} లో బాధ్యత తీసుకుంటున్నారు. దయచేసి:',
  'handoff.promptReadFiles': 'ముందుగా ఈ డైరెక్టరీని ఎంటర్ చేయండి లేదా చదవండి. ఉంటే DESIGN.md, README, ఉన్న HTML/CSS/JS, ఆస్తులు మరియు package.json కు ప్రాధాన్యత ఇవ్వండి.',
  'handoff.promptKeepDesign': 'ప్రస్తుత విజువల్ డిజైన్, లేఅవుట్, ఇంటరాక్షన్‌లు మరియు ఆస్తులను సంరక్షించండి. ఒక ప్లాన్ వద్ద ఆగకండి.',
  'handoff.promptProduceCode': 'నిజమైన అమలు చేయగలిగే {framework} కోడ్ ను సృష్టించండి లేదా సవరించండి. ప్రాజెక్ట్ ఇప్పటికే స్పష్టమైన స్టాక్ ను కలిగి ఉంటే, విభేదాన్ని పేర్కొనండి మరియు ఫలితాన్ని అమలు చేయగలిగేలా ఉంచండి.',
  'handoff.promptVerify': 'రన్, ప్రివ్యూ మరియు వెరిఫికేషన్ కమాండ్‌లను చెప్పడంతో ముగించండి.',
