  'brandEnrichment.title': 'AI Optimize',
  'brandEnrichment.body': 'Open Design బ్యాక్‌గ్రౌండ్‌లో లోతైన ఎక్స్‌ట్రాక్షన్ నడుపుతుంది, సరైన design-system స్కిల్స్‌ను ఆటోమేటిక్‌గా వర్తింపజేస్తుంది, ఈ సిస్టమ్‌ను అదే చోట అప్‌డేట్ చేస్తుంది. దీనికి 10-20 నిమిషాలు పడుతుంది; మీరు పని చేస్తూనే ఉండవచ్చు.',
