  'brandExtractionTranscript.next': 'తరువాత, ఒక ఫాలో-అప్ ఎంచుకోండి: మోడల్ టోకన్లు ఉపయోగించే ఏజెంట్ పాస్‌తో ఎక్స్‌ట్రాక్ట్ చేసిన design system రిఫైన్ చేయండి లేదా ఈ సిస్టమ్ ఉపయోగించి కొత్త డిజైన్ సృష్టించండి.',
