  'browserUse.action.run_project.output': 'బ్రౌజర్ ట్యాబ్ లో తెరిచిన గుర్తించబడిన dev సర్వర్ URL.',
  'browserUse.action.detect_project.output': 'ఫ్రేమ్‌వర్క్, ప్యాకేజీ మేనేజర్, ఇన్‌స్టాల్ కమాండ్, dev కమాండ్, మరియు పోర్ట్.',
  'browserUse.action.page_info.output': 'URL, టైటిల్, వివరణ, OG ఇమేజ్, థీమ్ కలర్, favicon, మరియు వ్యూపోర్ట్.',
