  'browserUse.action.click.output': 'వ్యూలోకి స్క్రోల్ చేసిన తర్వాత మొదటి సరిపోలిన ఎలిమెంట్ ను క్లిక్ చేయి.',
  'browserUse.action.type_text.output': 'ఒక ఇన్‌పుట్ ను నింపి input మరియు change ఈవెంట్‌లను డిస్పాచ్ చేయి.',
  'browserUse.action.scroll.output': 'ప్రస్తుత మరియు గరిష్ట స్క్రోల్ స్థానం.',
  'browserUse.action.extract_og_metadata.output': 'మెటా టైటిల్, వివరణ, కానోనికల్ URL, OG/Twitter కార్డ్‌లు, సోషల్ ఇమేజ్, మరియు థీమ్ కలర్.',
