  'chat.designToolbox.prompt.processRule': 'వర్క్‌ఫ్లో నియమం: ముందుగా ఎస్తెటిక్ లక్ష్యం మరియు పరిమితులను నిర్వచించండి, తర్వాత రిసోర్స్‌లను శోధించి మ్యాచ్ చేయండి; యూజర్ ఎంపిక అవసరమైనప్పుడు, ఒక పరిమిత-ఎంపిక UI జనరేట్ చేసి కన్ఫర్మేషన్ తర్వాత కొనసాగండి.',
