  'chat.example1Title': 'ఎడిటోరియల్ పిచ్ డెక్',
  'chat.example1Tag': 'మ్యాగజైన్',
  'chat.example1Prompt': 'ఒక డిజైన్ స్టూడియో కోసం seed రౌండ్ పైకి సేకరిస్తున్న ఒక 10-స్లయిడ్ ఎడిటోరియల్ పిచ్ డెక్ — Swiss-grid లేఅవుట్, బోల్డ్ డ్రాప్ క్యాప్స్ తో పెద్ద serif హెడ్‌లైన్‌లు, మోనోస్పేస్ సెక్షన్ నంబర్‌లు, పెద్ద మొత్తంలో నెగిటివ్ స్పేస్, మరియు టెక్స్ట్-హెవీ స్లయిడ్‌లతో కలిపి ఫుల్-బ్లీడ్ ఫోటో స్లయిడ్‌లు. కవర్, విజన్, మార్కెట్, ప్రొడక్ట్, ట్రాక్షన్, టీమ్, ఆస్క్, కాంటాక్ట్.',
  'chat.example2Title': 'SaaS అనలిటిక్స్ డాష్‌బోర్డ్',
  'chat.example2Tag': 'డేటా',
  'chat.example2Prompt': 'ఒక డెవలపర్-టూల్స్ SaaS కోసం డెన్స్ అనలిటిక్స్ డాష్‌బోర్డ్ — వారం-ఓవర్-వారం డెల్టాలతో KPI స్ట్రిప్, రెండు స్టాక్డ్ లైన్ చార్ట్‌లు (MRR మరియు యాక్టివ్ వర్క్‌స్పేస్‌లు), యూసేజ్ ప్రపంచ హీట్‌మ్యాప్, కోహార్ట్ రిటెన్షన్ గ్రిడ్, టాప్-కస్టమర్స్ లీడర్‌బోర్డ్, మరియు రియల్-టైమ్ ఈవెంట్ ఫీడ్. డార్క్ థీమ్, టాబ్యులర్ మోనోస్పేస్ న్యూమరల్స్, స్పార్క్‌లైన్ యాక్సెంట్స్.',
  'chat.example3Title': 'వార్షిక నివేదిక లాంగ్-స్క్రోల్',
  'chat.example3Tag': 'ఎడిటోరియల్',
  'chat.example3Prompt': 'ఒక క్లైమెట్ నాన్-ప్రాఫిట్ కోసం ఒక ఇంటరాక్టివ్ వార్షిక నివేదిక — పెద్ద పుల్-కోట్ బ్లాక్‌లు, డేటా విజువలైజేషన్‌లు (స్టాక్డ్ బార్స్, యానిమేటెడ్ కౌంటర్లు, ప్రాజెక్ట్ సైట్‌ల కోరోప్లెత్ మ్యాప్), ఫోటోగ్రఫీ బ్రేకర్లు, డోనర్ వాల్, మరియు చివరి కాల్-టు-యాక్షన్ కలిపే లాంగ్-స్క్రోల్ ఎడిటోరియల్ లేఅవుట్. మోడరన్ serif బాడీ, sans-serif చార్ట్ లేబుల్‌లు, ఎర్తీ పేపర్ ప్యాలెట్.',
