  'settings.customInstructionsTitle': 'గ్లోబల్ రూల్స్',
  'settings.customInstructionsHint': 'ప్రతి చాట్ లో OpenDesign పాటించాల్సిన స్థిరమైన ఇన్‌స్ట్రక్షన్స్. ఫ్యాక్ట్‌లు, ప్రాధాన్యతలు, మరియు ప్రాజెక్ట్ కాంటెక్స్ట్ ను మెమరీలుగా సేవ్ చేయండి.',
  'settings.customInstructionsPlaceholder': 'ఉదా. "ఎల్లప్పుడూ TypeScript ఉపయోగించు. ఫంక్షనల్ కంపోనెంట్‌లను ప్రాధాన్యం ఇవ్వు. రెస్పాన్స్‌లను సంక్షిప్తంగా ఉంచు."',
  'settings.memoryDescription': 'సేవ్ చేసిన ఫ్యాక్ట్‌లు, ప్రాధాన్యతలు, మరియు ప్రాజెక్ట్ కాంటెక్స్ట్ భవిష్యత్ చాట్‌లలో రీయూజ్ చేయబడతాయో లేదో నియంత్రించు.',
