  'settings.memoryEmptyHintEn': 'నేను డార్క్ మోడ్ ను ఇష్టపడతాను',
  'settings.memoryName': 'ఉదా. UI ప్రాధాన్యతలు',
  'settings.memoryDesc': 'ఒక వాక్యం — ఈ మెమరీ దేని గురించి?',
  'settings.memoryBody': '- రూల్ ఒకటి\n- రూల్ రెండు\n\nఎందుకు: ఐచ్ఛిక కారణం\nఎప్పుడు అప్లై చేయాలి: ఐచ్ఛిక స్కోప్',
  'settings.memoryBodyHint': 'ముందుగా రూల్‌లను బులెట్ చేయండి, తర్వాత ఐచ్ఛిక ఎందుకు మరియు ఎప్పుడు-అప్లై-చేయాలి లైన్‌లు. Markdown సపోర్ట్. లేదా పైన ఉన్న స్టార్టర్ క్లిక్ చేసి ఒక పని చేసే ఉదాహరణ లోడ్ చేయండి.',
  'settings.memoryStartersLabel': 'మొదలుపెట్టడానికి కావాలా? ఫారం నింపడానికి క్లిక్ చేయండి:',
  'settings.memoryStarterUserName': 'నా రోల్',
  'settings.memoryStarterUserDesc': 'నేను ఒక SaaS డిజైన్ టూల్ పై పనిచేసే ఫ్రంటెండ్ ఇంజనీర్',
  'settings.memoryStarterUserBody': '- రోల్: సీనియర్ ఫ్రంటెండ్ ఇంజనీర్\n- స్టాక్: React, TypeScript, Vite\n- డొమైన్: డిజైన్ / కాలాబరేషన్ టూల్స్\n- టైమ్‌జోన్: GMT+8 (Asia/Shanghai)\n\nఎప్పుడు అప్లై: ఏ చాట్ — ఉదాహరణలను వెబ్ ఫ్రంటెండ్ చుట్టూ ఫ్రేమ్ చేయి.',
  'settings.memoryStarterFeedbackName': 'UI ప్రాధాన్యతలు',
  'settings.memoryStarterFeedbackDesc': 'డార్క్ మోడ్, పెద్ద బాడీ టెక్స్ట్, తక్కువ సమాచార సాంద్రత',
  'settings.memoryStarterFeedbackBody': '- థీమ్: డిఫాల్ట్ గా డార్క్\n- బాడీ టెక్స్ట్: ≥ 18px\n- సమాచార సాంద్రత: వైట్‌స్పేస్ ను ప్రాధాన్యం ఇవ్వు, స్క్రీన్ కు తక్కువ ఐటమ్‌లు\n\nఎందుకు: సుదీర్ఘ సెషన్‌లలో తక్కువ కళ్ల అలసట.\nఎప్పుడు అప్లై: మీరు UI, వెబ్ పేజీలు, లేదా స్లయిడ్‌లను జనరేట్ చేసినప్పుడు.',
  'settings.memoryStarterProjectName': 'ప్రస్తుత ప్రాజెక్ట్',
  'settings.memoryStarterProjectDesc': 'Open Design v0.5 — చాట్-డ్రైవెన్ డిజైన్ ఎడిటర్',
  'settings.memoryStarterProjectBody': '- లక్ష్యం: ఈ క్వార్టర్ లో చాట్-డ్రైవెన్ ఎడిటర్ ను షిప్ చేయి\n- ప్రాధాన్యతలు: స్ట్రీమింగ్ రెండర్, లోకల్ మల్టీమోడల్, ఆఫ్‌లైన్-ఫస్ట్\n- స్టాక్: Next.js 16, Express డెమోన్, SQLite\n\nఎప్పుడు అప్లై: ఈ ప్రాజెక్ట్ గురించి ఏ సంభాషణలో అయినా.',
